"""Interactive one-command setup for DeSlop.

Generates a `.env` with strong secrets, a dashboard password hash, a random
OOB token, and (optionally) initializes the database. This closes the
"one-line install" gap: after ``deslop init`` you only need ``docker compose up``.
"""

from __future__ import annotations

import secrets
from dataclasses import dataclass, field
from pathlib import Path

from .web.auth import hash_password

ENV_TEMPLATE = """\
# Generated by `deslop init`. Keep this file secret.

DESLOP_ENV={env}
DESLOP_DATABASE_URL={database_url}
DESLOP_CONFIG_DIR={config_dir}

# --- LLM (your choice) ---
DESLOP_LLM_PROVIDER={llm_provider}
DESLOP_LLM_MODEL={llm_model}
DESLOP_ANTHROPIC_API_KEY=
DESLOP_OPENAI_API_KEY=
DESLOP_OPENAI_BASE_URL=
DESLOP_OLLAMA_BASE_URL=http://localhost:11434

# --- Embeddings (local by default) ---
DESLOP_EMBEDDING_PROVIDER=local
DESLOP_EMBEDDING_MODEL=BAAI/bge-m3
DESLOP_EMBEDDING_DIM=1024

# --- Execution limits ---
DESLOP_REPRO_HEADER=X-Repro-Validator
DESLOP_MAX_REQUESTS_PER_RUN=50
DESLOP_MAX_RUN_SECONDS=120
DESLOP_RATE_LIMIT_RPS=5
DESLOP_ALLOW_PRODUCTION=false

# --- OOB listener ---
DESLOP_OOB_BASE_URL={oob_base_url}

# --- Dashboard auth ---
DESLOP_DASHBOARD_USER={dashboard_user}
DESLOP_DASHBOARD_PASSWORD_HASH={dashboard_password_hash}

# --- Notifications (leave blank to disable) ---
DESLOP_NOTIFY_ENABLED={notify_enabled}
DESLOP_SLACK_WEBHOOK_URL=
DESLOP_TELEGRAM_BOT_TOKEN=
DESLOP_TELEGRAM_CHAT_ID=
DESLOP_NOTIFY_BASE_URL={notify_base_url}

# --- Intake anti-abuse ---
DESLOP_INTAKE_RATE_LIMIT=10
DESLOP_INTAKE_RATE_WINDOW_SECONDS=60
DESLOP_BLACKLIST_ENABLED=true
DESLOP_BLACKLIST_FILE=./data/blacklist.json

DESLOP_LOG_LEVEL=INFO
"""


@dataclass
class InitResult:
    env_path: Path
    dashboard_password: str
    created: bool
    notes: list[str] = field(default_factory=list)


def generate_env(
    *,
    env: str = "dev",
    dashboard_user: str = "admin",
    dashboard_password: str | None = None,
    database_url: str | None = None,
    config_dir: str = "./config/programs",
    llm_provider: str = "none",
    llm_model: str = "",
    oob_base_url: str = "http://localhost:8080",
    notify_base_url: str = "http://localhost:8000",
    notify_enabled: bool = False,
) -> tuple[str, str]:
    """Render the .env contents and return (contents, plaintext_password)."""
    password = dashboard_password or secrets.token_urlsafe(16)
    if database_url is None:
        database_url = "postgresql+psycopg://deslop:deslop@localhost:5432/deslop"
    contents = ENV_TEMPLATE.format(
        env=env,
        database_url=database_url,
        config_dir=config_dir,
        llm_provider=llm_provider,
        llm_model=llm_model,
        oob_base_url=oob_base_url,
        dashboard_user=dashboard_user,
        dashboard_password_hash=hash_password(password),
        notify_enabled=str(notify_enabled).lower(),
        notify_base_url=notify_base_url,
    )
    return contents, password


def write_env(
    path: str | Path = ".env",
    *,
    force: bool = False,
    dashboard_password: str | None = None,
    **kwargs,
) -> InitResult:
    """Write a generated .env file. Refuses to overwrite unless ``force``."""
    p = Path(path)
    if p.exists() and not force:
        return InitResult(
            env_path=p,
            dashboard_password="",
            created=False,
            notes=[f"{p} already exists; use --force to overwrite"],
        )
    contents, password = generate_env(dashboard_password=dashboard_password, **kwargs)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(contents, encoding="utf-8")
    notes = [
        "Edit the .env if you want to change the database URL, LLM provider, or SMTP.",
        "Start the stack with:  docker compose up -d",
        "Generate a program config by copying config/programs/example-acme-cloud.yaml",
    ]
    return InitResult(env_path=p, dashboard_password=password, created=True, notes=notes)
